// Yang kamu tulis — Keranjang.tsx
type ItemKeranjang = { nama: string; jumlah: number };

export function ringkasKeranjang(items: ItemKeranjang[]): string {
  const total = items.reduce((n, item) => n + item.jumlah, 0);
  return `${total} barang`;
}

// Yang sampai ke HP setelah tipe dibuang — JavaScript murni
export function ringkasKeranjang(items) {
  const total = items.reduce((n, item) => n + item.jumlah, 0);
  return `${total} barang`;
}

